#[cfg(test)]
mod i75_l5_zip_lookup_switch_tests {
    use super::*;

    /// Interpreter round i3 wave 75, lane L5:
    /// `CRATONVM_ZIP_CEN_ACCESSOR_INTRINSICS` and
    /// `CRATONVM_ZIP_CODER_COMPARE_INTRINSIC` are read once per registry with
    /// the `truthy_word` rule, each independent of the other (every case sets
    /// both words explicitly, so no assertion here depends on a default).
    #[test]
    fn the_zip_lookup_switches_are_read_per_registry() {
        fn read(cen: &str, coder: &str) -> (bool, bool) {
            cratonvm_types::flags::with_thread_overrides(
                &[
                    ("CRATONVM_ZIP_CEN_ACCESSOR_INTRINSICS", Some(cen)),
                    ("CRATONVM_ZIP_CODER_COMPARE_INTRINSIC", Some(coder)),
                ],
                || {
                    let r = NativeMethodRegistry::new();
                    (
                        r.zip_cen_accessor_intrinsics(),
                        r.zip_coder_compare_intrinsic(),
                    )
                },
            )
        }
        assert_eq!(read("0", "0"), (false, false));
        assert_eq!(read("1", "0"), (true, false));
        assert_eq!(read("0", "true"), (false, true));
        assert_eq!(read("true", "1"), (true, true));
    }

    /// Interpreter round i3 wave 76, lane L5:
    /// `CRATONVM_ZIP_ENTRY_MISS_INTRINSIC` is read once per registry with the
    /// `truthy_word` rule (every case sets the word explicitly).
    #[test]
    fn the_zip_entry_miss_switch_is_read_per_registry() {
        fn read(word: &str) -> bool {
            cratonvm_types::flags::with_thread_overrides(
                &[("CRATONVM_ZIP_ENTRY_MISS_INTRINSIC", Some(word))],
                || NativeMethodRegistry::new().zip_entry_miss_intrinsic(),
            )
        }
        assert!(!read("0"));
        assert!(!read("off"));
        assert!(read("1"));
        assert!(read("true"));
    }

    /// Interpreter round i3 wave 77, lane L5:
    /// `CRATONVM_ZIP_ENTRY_HIT_INTRINSIC` and `CRATONVM_REFERENCE_LAYOUT_MEMO`
    /// are read once per registry with the `truthy_word` rule, each
    /// independent of the other and of the miss switch (every case sets all
    /// three words explicitly, so nothing here depends on a default); the
    /// setters override the env read; a fresh registry's layout slot is empty.
    #[test]
    fn i77_the_hit_and_reference_layout_switches_are_read_per_registry() {
        fn read(miss: &str, hit: &str, memo: &str) -> (bool, bool, bool) {
            cratonvm_types::flags::with_thread_overrides(
                &[
                    ("CRATONVM_ZIP_ENTRY_MISS_INTRINSIC", Some(miss)),
                    ("CRATONVM_ZIP_ENTRY_HIT_INTRINSIC", Some(hit)),
                    ("CRATONVM_REFERENCE_LAYOUT_MEMO", Some(memo)),
                ],
                || {
                    let r = NativeMethodRegistry::new();
                    (
                        r.zip_entry_miss_intrinsic(),
                        r.zip_entry_hit_intrinsic(),
                        r.reference_layout_memo(),
                    )
                },
            )
        }
        assert_eq!(read("0", "0", "0"), (false, false, false));
        assert_eq!(read("0", "1", "0"), (false, true, false));
        assert_eq!(read("1", "off", "true"), (true, false, true));
        assert_eq!(read("0", "true", "1"), (false, true, true));

        let mut r = NativeMethodRegistry::new();
        r.set_zip_entry_hit_intrinsic(true);
        r.set_reference_layout_memo(true);
        assert!(r.zip_entry_hit_intrinsic() && r.reference_layout_memo());
        r.set_zip_entry_hit_intrinsic(false);
        r.set_reference_layout_memo(false);
        assert!(!r.zip_entry_hit_intrinsic() && !r.reference_layout_memo());
        assert!(r.reference_layout_slot().get().is_none());
    }

    /// `CRATONVM_INFLATER_INPUT_WINDOW` (same wave and lane) is read once per
    /// registry with the `truthy_word` rule.
    #[test]
    fn the_inflater_input_window_switch_is_read_per_registry() {
        fn read(word: &str) -> bool {
            cratonvm_types::flags::with_thread_overrides(
                &[("CRATONVM_INFLATER_INPUT_WINDOW", Some(word))],
                || NativeMethodRegistry::new().inflater_input_window(),
            )
        }
        assert!(!read("0"));
        assert!(read("1"));
        assert!(read("true"));
    }

    /// `CRATONVM_INFLATER_SHARDED_TABLE` (interpreter round i5 wave 100,
    /// lane L5) is read once per registry, default on since
    /// the w100 triage.
    #[test]
    fn the_inflater_sharded_table_switch_is_read_per_registry() {
        fn read(word: Option<&str>) -> bool {
            cratonvm_types::flags::with_thread_overrides(
                &[("CRATONVM_INFLATER_SHARDED_TABLE", word)],
                || NativeMethodRegistry::new().inflater_sharded_table(),
            )
        }
        assert!(read(None));
        assert!(!read(Some("0")));
        assert!(read(Some("1")));
        assert!(read(Some("true")));
    }
}

