/// The rows `CRATONVM_INTRINSIC_BODY_COMPILES_ROWS` stands for when it is
/// UNSET (or set to a truthy word: `1`, `true`, `on`, `yes`, which is what
/// `CRATONVM_JIT=intrinsic-body-compiles-rows` writes).
///
/// Interpreter round i3 wave 81, lane L4: `finder-mint`, the one row that won
/// under the JIT (host, wave 80: `L4W77FinderMintBench` `find-getter` 15.5 ->
/// 3.1 us, every probe SAME); `method-type-intern` and `ste-to-string` lost
/// and stay off. THE FLIP IS THIS ONE LINE: `""` restores the wave-80 default
/// (no row). `=0`, `=none` or `=` (empty) turns every row off per run; the
/// INVENTORY row's `off_word` is `Some("0")`.
///
/// Interpreter round i4 wave 84 (orchestrator triage): `method-finder-mint`
/// joins the default (Windows, Temurin 25.0.3, `L4W81MethodFinderBench
/// --jdk-only`, 3 interleaved reps, medians: find-virtual 16.8 -> 3.9 us,
/// find-static 41.8 -> 3.0, find-special 15.9 -> 3.3, find-constructor 14.4
/// -> 5.1, find-virtual-ref 87.0 -> 3.2, unreflect-method 24.0 -> 3.5;
/// checksums equal). Removing it from this line restores the wave-83 default.
pub const INTRINSIC_BODY_COMPILES_ROWS_DEFAULT: &str = "finder-mint,method-finder-mint";

/// `CRATONVM_INTRINSIC_BODY_COMPILES_ROWS` as read: `None` (unset) is
/// [`INTRINSIC_BODY_COMPILES_ROWS_DEFAULT`]; a set value is parsed by
/// [`parse_intrinsic_body_compiles_rows`], so an empty value lists no row.
fn read_intrinsic_body_compiles_rows(value: Option<&str>) -> Vec<String> {
    parse_intrinsic_body_compiles_rows(value.unwrap_or(INTRINSIC_BODY_COMPILES_ROWS_DEFAULT))
}

/// The row tokens of `CRATONVM_INTRINSIC_BODY_COMPILES_ROWS` (interpreter
/// round i3 wave 80, lane L4): comma-separated, trimmed, ASCII-lowercased;
/// empty items and the off words (`0`, `false`, `off`, `no`, `none`) dropped.
/// Wave 81: a truthy word (`1`, `true`, `on`, `yes`) stands for the default
/// rows ([`INTRINSIC_BODY_COMPILES_ROWS_DEFAULT`]), so the group token's
/// "on" (`=1`) means "the default set", never a row named `1`.
fn parse_intrinsic_body_compiles_rows(value: &str) -> Vec<String> {
    let mut rows: Vec<String> = Vec::new();
    for item in value.split(',') {
        let row = item.trim().to_ascii_lowercase();
        if row.is_empty() || matches!(row.as_str(), "0" | "false" | "off" | "no" | "none") {
            continue;
        }
        if matches!(row.as_str(), "1" | "true" | "on" | "yes") {
            for default_row in INTRINSIC_BODY_COMPILES_ROWS_DEFAULT.split(',') {
                let default_row = default_row.trim().to_ascii_lowercase();
                if !default_row.is_empty() && !rows.contains(&default_row) {
                    rows.push(default_row);
                }
            }
            continue;
        }
        if !rows.contains(&row) {
            rows.push(row);
        }
    }
    rows
}

#[cfg(test)]
mod i80_l4_intrinsic_body_compiles_rows_tests {
    use super::*;

    /// `CRATONVM_INTRINSIC_BODY_COMPILES_ROWS` (interpreter round i3 wave 80,
    /// lane L4): a listed row takes the body-compiles path alone; the global
    /// switch still covers every row. Values set explicitly.
    #[test]
    fn i80_a_listed_row_adopts_the_body_compiles_path_alone() {
        assert_eq!(
            parse_intrinsic_body_compiles_rows(" Finder-Mint, ,ste-to-string,finder-mint,0,off"),
            vec!["finder-mint".to_string(), "ste-to-string".to_string()]
        );
        assert!(parse_intrinsic_body_compiles_rows("").is_empty());
        assert!(parse_intrinsic_body_compiles_rows("none").is_empty());

        let read = |value: Option<&str>| {
            cratonvm_types::flags::with_thread_overrides(
                &[("CRATONVM_INTRINSIC_BODY_COMPILES_ROWS", value)],
                || {
                    NativeMethodRegistry::new()
                        .intrinsic_body_compiles_rows
                        .clone()
                },
            )
        };
        assert_eq!(read(Some("finder-mint")), vec!["finder-mint".to_string()]);
        assert!(read(Some("0")).is_empty());
        // Wave 81: unset is the default set, whatever it is (no default pinned).
        assert_eq!(
            read(None),
            parse_intrinsic_body_compiles_rows(INTRINSIC_BODY_COMPILES_ROWS_DEFAULT)
        );

        let mut r = NativeMethodRegistry::new();
        r.set_intrinsic_body_compiles(false);
        r.set_intrinsic_body_compiles_rows("");
        r.set_jit_enabled(true);
        assert!(!r.interpreted_intrinsic_registers_row("finder-mint"));
        r.mark_body_compilable_intrinsic_row("finder-mint", "p/C", "m", "()V");
        assert!(
            !r.is_body_compilable_intrinsic("p/C", "m", "()V"),
            "no mark without a row"
        );

        r.set_intrinsic_body_compiles_rows("finder-mint");
        assert!(r.interpreted_intrinsic_registers_row("finder-mint"));
        assert!(!r.interpreted_intrinsic_registers_row("method-type-intern"));
        assert!(
            !r.interpreted_intrinsic_registers(),
            "the global answer does not move"
        );
        r.mark_body_compilable_intrinsic_row("method-type-intern", "p/D", "m", "()V");
        r.mark_body_compilable_intrinsic_row("finder-mint", "p/C", "m", "()V");
        assert!(r.is_body_compilable_intrinsic("p/C", "m", "()V"));
        assert!(!r.is_body_compilable_intrinsic("p/D", "m", "()V"));

        // No JIT: every row registers, as before.
        r.set_jit_enabled(false);
        assert!(r.interpreted_intrinsic_registers_row("method-type-intern"));
        // The global switch covers every row.
        r.set_jit_enabled(true);
        r.set_intrinsic_body_compiles(true);
        assert!(r.interpreted_intrinsic_registers_row("method-type-intern"));
    }

    /// Wave 81 (lane L4): unset reads as
    /// [`INTRINSIC_BODY_COMPILES_ROWS_DEFAULT`]; a set value -- empty included
    /// -- is parsed as written; every off word (the INVENTORY `off_word` `0`
    /// among them) lists no row; a truthy word lists the default rows. The
    /// default only ever names `finder-mint` (the intern memo and the
    /// `StackTraceElement.toString` rows lost under the JIT and stay off).
    #[test]
    fn i81_unset_is_the_default_set_and_an_off_word_or_empty_lists_no_row() {
        let default = parse_intrinsic_body_compiles_rows(INTRINSIC_BODY_COMPILES_ROWS_DEFAULT);
        assert!(
            default
                .iter()
                .all(|r| r == "finder-mint" || r == "method-finder-mint"),
            "only the finder mint rows may be on by default: {default:?}"
        );
        assert_eq!(read_intrinsic_body_compiles_rows(None), default);
        for off in ["", "0", "none", "off", "false", "no", " , "] {
            assert!(
                read_intrinsic_body_compiles_rows(Some(off)).is_empty(),
                "{off:?}"
            );
        }
        for on in ["1", "true", "ON", "yes"] {
            assert_eq!(
                read_intrinsic_body_compiles_rows(Some(on)),
                default,
                "{on:?}"
            );
        }
        assert_eq!(
            read_intrinsic_body_compiles_rows(Some("method-type-intern")),
            vec!["method-type-intern".to_string()],
            "a set list replaces the default rows, it does not add to them"
        );
        let read = |value: Option<&str>| {
            cratonvm_types::flags::with_thread_overrides(
                &[("CRATONVM_INTRINSIC_BODY_COMPILES_ROWS", value)],
                || {
                    NativeMethodRegistry::new()
                        .intrinsic_body_compiles_rows
                        .clone()
                },
            )
        };
        assert_eq!(read(None), default);
        assert!(read(Some("0")).is_empty());
        assert!(read(Some("")).is_empty());
    }
}

#[cfg(test)]
mod i79_l5_intrinsic_body_compiles_tests {
    use super::*;

    /// `CRATONVM_INTRINSIC_BODY_COMPILES` (interpreter round i3 wave 79, lane
    /// L5) is read once per registry with the `truthy_word` rule; a mark is
    /// kept only with it on; `interpreted_intrinsic_registers` is "no JIT, or
    /// the switch". Values set explicitly.
    #[test]
    fn i79_the_body_compiles_switch_and_marks() {
        fn read(value: &str) -> bool {
            cratonvm_types::flags::with_thread_overrides(
                &[("CRATONVM_INTRINSIC_BODY_COMPILES", Some(value))],
                || NativeMethodRegistry::new().intrinsic_body_compiles(),
            )
        }
        assert!(read("1"));
        assert!(!read("0"));

        let mut r = NativeMethodRegistry::new();
        r.set_intrinsic_body_compiles(false);
        // Wave 81: the rows list defaults to `finder-mint`, which also opens
        // the gate; this test is about the global switch alone.
        r.set_intrinsic_body_compiles_rows("");
        r.mark_body_compilable_intrinsic("p/C", "m", "()V");
        assert!(
            !r.is_body_compilable_intrinsic("p/C", "m", "()V"),
            "no mark without the switch"
        );
        r.set_jit_enabled(true);
        assert!(!r.interpreted_intrinsic_registers());
        r.set_jit_enabled(false);
        assert!(r.interpreted_intrinsic_registers());

        r.set_intrinsic_body_compiles(true);
        r.set_jit_enabled(true);
        assert!(r.interpreted_intrinsic_registers());
        r.mark_body_compilable_intrinsic("p/C", "m", "()V");
        r.mark_body_compilable_intrinsic("p/C", "m", "()V");
        assert!(r.is_body_compilable_intrinsic("p/C", "m", "()V"));
        assert!(!r.is_body_compilable_intrinsic("p/C", "m", "()I"));
        assert!(!r.is_body_compilable_intrinsic("p/D", "m", "()V"));
        r.set_intrinsic_body_compiles(false);
        assert!(
            !r.is_body_compilable_intrinsic("p/C", "m", "()V"),
            "the switch gates the answer"
        );
    }
}

