#[cfg(test)]
mod i138_l2_strict_family_bridges_tests {
    use super::*;

    fn bridge_cb(_ctx: &mut dyn NativeContext, _args: &[Value]) -> MethodCallResult {
        Ok(None)
    }

    /// Interpreter round i7 wave 138, lane L2
    /// (`i137-orch-jdk-only-soft-and-phantom-refersto-cost-4-us`):
    /// `CRATONVM_STRICT_FAMILY_BRIDGES` (default ON since interpreter round i7
    /// wave 144; `=0` off) drops a
    /// `CompatFamily::bridges` triple under `JdkOnly` over a real JDK only;
    /// `Compatible` without its row, the synthetic library, a non-family
    /// triple and an `Intrinsic` are untouched.
    #[test]
    fn strict_family_bridges_drop_only_family_bridges_under_jdk_only() {
        fn registered(
            value: Option<&'static str>,
            mode: CompatibilityMode,
            real_jdk: bool,
            class: &str,
            kind: NativeKind,
        ) -> bool {
            cratonvm_types::flags::with_thread_overrides(
                &[("CRATONVM_STRICT_FAMILY_BRIDGES", value)],
                || {
                    let mut r = NativeMethodRegistry::new();
                    r.set_compatibility_mode(mode);
                    r.set_real_jdk(real_jdk);
                    let prev = r.current_category();
                    r.set_category(kind);
                    r.register(class, "refersTo", "(Ljava/lang/Object;)Z", bridge_cb);
                    r.set_category(prev);
                    r.kind_of(class, "refersTo", "(Ljava/lang/Object;)Z").is_some()
                },
            )
        }
        let strict = CompatibilityMode::JdkOnly;
        for class in [
            "java/lang/ref/Reference",
            "java/lang/ref/SoftReference",
            "java/lang/ref/PhantomReference",
        ] {
            assert!(crate::retired_shadow::is_compat_family_bridge(
                class,
                "refersTo",
                "(Ljava/lang/Object;)Z"
            ));
            // Default ON (i7 wave 144): dropped; `=0` registers it as before.
            assert!(!registered(None, strict, true, class, NativeKind::Bridge));
            assert!(registered(Some("0"), strict, true, class, NativeKind::Bridge));
            // On: dropped under JdkOnly over a real JDK.
            assert!(!registered(Some("1"), strict, true, class, NativeKind::Bridge));
            // Not over the synthetic library, and an Intrinsic stays.
            assert!(registered(Some("1"), strict, false, class, NativeKind::Bridge));
            assert!(registered(Some("1"), strict, true, class, NativeKind::Intrinsic));
        }
        // A triple outside every family's `bridges` is untouched.
        assert!(!crate::retired_shadow::is_compat_family_bridge(
            "java/lang/ref/Reference",
            "refersTo0",
            "(Ljava/lang/Object;)Z"
        ));
    }
}

/// j27 wave 7 (lane T1LOOPSTATIC, backlog row SBEMPTY17-4):
/// `CRATONVM_STRING_LITERAL_IDENTITY` is a per-registry (per-VM) answer read
/// at construction, not a process latch: two registries built under different
/// overrides answer differently, and a later override does not change a built
/// one.
#[cfg(test)]
mod j27_t1loopstatic_string_literal_identity_tests {
    use super::NativeMethodRegistry;

    const KEY: &str = "CRATONVM_STRING_LITERAL_IDENTITY";

    fn built_with(word: Option<&str>) -> NativeMethodRegistry {
        cratonvm_types::flags::with_thread_overrides(&[(KEY, word)], NativeMethodRegistry::new)
    }

    #[test]
    fn each_registry_reads_its_own_answer() {
        let on = built_with(None);
        let off = built_with(Some("0"));
        assert!(on.string_literal_identity(), "default ON");
        assert!(!off.string_literal_identity(), "=0 kill");
        assert!(on.string_literal_identity(), "the first registry kept its answer");
    }

    #[test]
    fn a_built_registry_ignores_a_later_override() {
        let off = built_with(Some("0"));
        let still = cratonvm_types::flags::with_thread_overrides(&[(KEY, None)], || {
            off.string_literal_identity()
        });
        assert!(!still);
    }
}
